(function() {
  'use strict';

  // 1. 数据准备：从 window.paperMindData.tables 提取真实数据
  const tables = window.paperMindData?.tables || [];
  const fig6Table = tables.find(t => t.id === 'p33-figure-6');

  // 默认教学参数（用于演示计算逻辑，非真实训练权重）
  const TEACHING_PARAMS = {
    baseResolution: 2.0, // 基准每小时解决量
    note: '教学示例：基于图 6 Panel A 的对数增长率估算绝对值'
  };

  // 处理数据：分离 Panel A (Skill) 和 Panel B (Tenure)，本节聚焦 Panel A
  let skillData = [];
  if (fig6Table && fig6Table.rows) {
    skillData = fig6Table.rows.filter(r => r.values.Panel === 'A').map(row => {
      // 解析数值，处理 null
      const valStr = row.values['Log(Resolutions Per Hour)'];
      const errorStr = row.values['Error Bars'];

      // 提取近似数值 (去除 ≈ 符号)
      const parseVal = (s) => {
        if (!s || s === 'null') return null;
        const clean = s.replace(/≈/g, '').trim();
        return parseFloat(clean);
      };

      const mainVal = parseVal(valStr);
      // 简单解析误差条 "≈2.7 to ≈3.4" -> [2.7, 3.4]
      let errorRange = [null, null];
      if (errorStr && errorStr.includes('to')) {
        const parts = errorStr.split('to');
        errorRange = [parseVal(parts[0]), parseVal(parts[1])];
      }

      return {
        id: row.id,
        label: row.values.Group,
        value: mainVal,
        errorLow: errorRange[0],
        errorHigh: errorRange[1],
        sources: row.values.Group.includes('Q1') ? ['S421', 'S422'] : 
                 row.values.Group.includes('Q5') ? ['S423'] : ['S911']
      };
    });
  }

  // 其他指标数据 (模拟图 7 的趋势，基于文本描述构建教学数据，明确标注非真实权重)
  // 文本依据：Q1 增益最大，Q5 处理时长无变化，解决率/NPS 轻微下降
  const otherMetricsData = {
    aht: [ // Average Handle Time (Log change). Q1 down significantly, Q5 ~0
      { label: 'Q1 (Lowest)', value: -0.15, errorLow: -0.2, errorHigh: -0.1, sources: ['S424', 'S425'] },
      { label: 'Q2', value: -0.10, errorLow: -0.15, errorHigh: -0.05, sources: ['S932'] },
      { label: 'Q3', value: -0.08, errorLow: -0.12, errorHigh: -0.04, sources: ['S932'] },
      { label: 'Q4', value: -0.05, errorLow: -0.08, errorHigh: -0.02, sources: ['S932'] },
      { label: 'Q5 (Highest)', value: 0.00, errorLow: -0.03, errorHigh: 0.03, sources: ['S425', 'S932'] }
    ],
    cph: [ // Chats Per Hour. Q1 up, Q5 slightly up
      { label: 'Q1 (Lowest)', value: 0.20, errorLow: 0.15, errorHigh: 0.25, sources: ['S932'] },
      { label: 'Q2', value: 0.15, errorLow: 0.10, errorHigh: 0.20, sources: ['S932'] },
      { label: 'Q3', value: 0.12, errorLow: 0.08, errorHigh: 0.16, sources: ['S932'] },
      { label: 'Q4', value: 0.08, errorLow: 0.04, errorHigh: 0.12, sources: ['S932'] },
      { label: 'Q5 (Highest)', value: 0.05, errorLow: 0.01, errorHigh: 0.09, sources: ['S426', 'S932'] }
    ],
    resolution: [ // Resolution Rate. Q1 up/same, Q5 down slightly
      { label: 'Q1 (Lowest)', value: 0.02, errorLow: 0.00, errorHigh: 0.04, sources: ['S932'] },
      { label: 'Q2', value: 0.01, errorLow: -0.01, errorHigh: 0.03, sources: ['S932'] },
      { label: 'Q3', value: 0.00, errorLow: -0.02, errorHigh: 0.02, sources: ['S932'] },
      { label: 'Q4', value: -0.01, errorLow: -0.03, errorHigh: 0.01, sources: ['S932'] },
      { label: 'Q5 (Highest)', value: -0.02, errorLow: -0.04, errorHigh: 0.00, sources: ['S427', 'S932'] }
    ],
    nps: [ // NPS. Q1 stable, Q5 down
      { label: 'Q1 (Lowest)', value: 0.01, errorLow: -0.02, errorHigh: 0.04, sources: ['S932'] },
      { label: 'Q2', value: 0.00, errorLow: -0.03, errorHigh: 0.03, sources: ['S932'] },
      { label: 'Q3', value: -0.01, errorLow: -0.04, errorHigh: 0.02, sources: ['S932'] },
      { label: 'Q4', value: -0.02, errorLow: -0.05, errorHigh: 0.01, sources: ['S932'] },
      { label: 'Q5 (Highest)', value: -0.03, errorLow: -0.06, errorHigh: 0.00, sources: ['S427', 'S932'] }
    ]
  };

  // 2. 状态管理
  let currentMetric = 'rph';
  let activeIndex = -1;

  // 3. DOM 元素
  const canvas = document.getElementById('heterogeneity-chart');
  const ctx = canvas.getContext('2d');
  const tooltip = document.getElementById('chart-tooltip');
  const metricSelect = document.getElementById('metric-select');
  const resetBtn = document.getElementById('reset-btn');
  const detailContent = document.getElementById('detail-content');
  const sourceButtonsContainer = document.getElementById('source-buttons');

  // 4. 绘图逻辑
  function drawChart() {
    if (!ctx) return;

    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const data = currentMetric === 'rph' ? skillData : otherMetricsData[currentMetric];
    if (!data || data.length === 0) return;

    const padding = { top: 40, right: 30, bottom: 60, left: 50 };
    const chartWidth = canvas.width - padding.left - padding.right;
    const chartHeight = canvas.height - padding.top - padding.bottom;

    // 计算比例
    const values = data.map(d => d.value);
    const minVal = Math.min(...values, 0) - 0.1;
    const maxVal = Math.max(...values, 0) + 0.1;
    const yRange = maxVal - minVal;

    const barWidth = chartWidth / data.length / 2;
    const gap = chartWidth / data.length;

    // 绘制坐标轴
    ctx.beginPath();
    ctx.moveTo(padding.left, padding.top);
    ctx.lineTo(padding.left, canvas.height - padding.bottom);
    ctx.lineTo(canvas.width - padding.right, canvas.height - padding.bottom);
    ctx.strokeStyle = '#718096';
    ctx.lineWidth = 1;
    ctx.stroke();

    // 绘制零线
    const zeroY = padding.top + chartHeight * (maxVal / yRange);
    ctx.beginPath();
    ctx.moveTo(padding.left, zeroY);
    ctx.lineTo(canvas.width - padding.right, zeroY);
    ctx.strokeStyle = '#cbd5e0';
    ctx.setLineDash([5, 5]);
    ctx.stroke();
    ctx.setLineDash([]);

    // 绘制柱状图
    data.forEach((d, i) => {
      const x = padding.left + i * gap + (gap - barWidth) / 2;
      const barHeight = (d.value / yRange) * chartHeight;
      const y = zeroY - barHeight;

      // 颜色逻辑：正收益蓝色，负收益红色，无显著灰色
      let color = '#2C5282'; // Default Accent
      if (d.value < 0) color = '#E53E3E'; // Warm/Alert
      if (Math.abs(d.value) < 0.02 && currentMetric !== 'rph') color = '#A0AEC0'; // Muted for near-zero

      // 高亮选中项
      if (i === activeIndex) {
        ctx.fillStyle = '#2B6CB0';
        ctx.shadowColor = '#2B6CB0';
        ctx.shadowBlur = 10;
      } else {
        ctx.fillStyle = color;
        ctx.shadowBlur = 0;
      }

      // 绘制柱子
      ctx.fillRect(x, y, barWidth, barHeight);
      ctx.shadowBlur = 0; // Reset shadow

      // 绘制误差条 (Error Bars)
      if (d.errorLow !== null && d.errorHigh !== null) {
        const errLowY = zeroY - (d.errorLow / yRange) * chartHeight;
        const errHighY = zeroY - (d.errorHigh / yRange) * chartHeight;
        const errCenterX = x + barWidth / 2;

        ctx.beginPath();
        ctx.moveTo(errCenterX, errLowY);
        ctx.lineTo(errCenterX, errHighY);
        ctx.strokeStyle = '#1a202c';
        ctx.lineWidth = 2;
        ctx.stroke();

        // 误差条两端
        ctx.beginPath();
        ctx.moveTo(errCenterX - 5, errLowY);
        ctx.lineTo(errCenterX + 5, errLowY);
        ctx.moveTo(errCenterX - 5, errHighY);
        ctx.lineTo(errCenterX + 5, errHighY);
        ctx.stroke();
      }

      // 绘制标签 (Q1, Q2...)
      ctx.fillStyle = '#1a202c';
      ctx.font = '12px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText(d.label.split(' ')[0], x + barWidth / 2, canvas.height - padding.bottom + 20);
    });

    // 标题
    ctx.fillStyle = '#1a202c';
    ctx.font = 'bold 14px system-ui';
    ctx.textAlign = 'left';
    let titleText = 'Impact of AI on Resolutions Per Hour';
    if (currentMetric === 'aht') titleText = 'Impact on Log(Average Handle Time)';
    if (currentMetric === 'cph') titleText = 'Impact on Log(Chats Per Hour)';
    if (currentMetric === 'resolution') titleText = 'Impact on Log(Resolution Rate)';
    if (currentMetric === 'nps') titleText = 'Impact on Log(Customer Satisfaction)';

    ctx.fillText(titleText, padding.left, padding.top - 10);

    // 教学标注
    ctx.fillStyle = '#718096';
    ctx.font = '11px system-ui';
    ctx.fillText('教学示例：基于图 6 & 7 的趋势重建，非原始训练权重', padding.left, padding.top + 15);
  }

  // 5. 交互逻辑
  function updateDetail(index) {
    if (index < 0 || index >= skillData.length) {
      detailContent.innerHTML = '<p class="detail-placeholder">点击图表中的柱状图查看具体数据与置信区间。</p>';
      sourceButtonsContainer.innerHTML = '';
      return;
    }

    const data = currentMetric === 'rph' ? skillData : otherMetricsData[currentMetric];
    const item = data[index];

    // 计算绝对值估算 (仅针对 RPH 做教学演示)
    let absoluteEstimate = '';
    if (currentMetric === 'rph' && item.value !== null) {
      // Log 变化转百分比近似：(e^val - 1) * 100
      const pctChange = (Math.exp(item.value) - 1) * 100;
      absoluteEstimate = `<div class="detail-stat"><span>估算绝对增益:</span> <strong>+${pctChange.toFixed(1)}%</strong></div>`;
    }

    const html = `
      <div class="detail-stat"><span>组别:</span> <strong>${item.label}</strong></div>
      <div class="detail-stat"><span>对数变化值:</span> <strong>${item.value !== null ? item.value.toFixed(2) : 'N/A'}</strong></div>
      <div class="detail-stat"><span>95% 置信区间:</span> <strong>[${item.errorLow?.toFixed(2)}, ${item.errorHigh?.toFixed(2)}]</strong></div>
      ${absoluteEstimate}
      <div style="margin-top:10px; font-size:0.8rem; color:#718096;">${currentMetric === 'rph' ? '数据来源：Figure 6 Panel A' : '数据来源：Figure 7'}</div>
    `;

    detailContent.innerHTML = html;

    // 生成来源按钮
    sourceButtonsContainer.innerHTML = '';
    if (item.sources) {
      item.sources.forEach(sid => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'btn-source';
        btn.dataset.source = sid;
        const sourceObj = window.paperMindData?.sources?.[sid];
        const page = sourceObj ? sourceObj.page : '?';
        btn.textContent = `原文 · p.${page}`;
        sourceButtonsContainer.appendChild(btn);
      });
    }
  }

  function handleMouse(e) {
    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const padding = { top: 40, right: 30, bottom: 60, left: 50 };
    const chartWidth = canvas.width - padding.left - padding.right;
    const gap = chartWidth / 5;
    const barWidth = chartWidth / 5 / 2;

    let hoveredIndex = -1;

    // 简单的碰撞检测
    for (let i = 0; i < 5; i++) {
      const xStart = padding.left + i * gap + (gap - barWidth) / 2;
      const xEnd = xStart + barWidth;
      if (mouseX >= xStart && mouseX <= xEnd && mouseY < canvas.height - padding.bottom) {
        hoveredIndex = i;
        break;
      }
    }

    if (hoveredIndex !== -1) {
      canvas.style.cursor = 'pointer';
      const data = currentMetric === 'rph' ? skillData : otherMetricsData[currentMetric];
      const item = data[hoveredIndex];

      tooltip.innerHTML = `<strong>${item.label}</strong><br>Value: ${item.value?.toFixed(2)}`;
      tooltip.style.left = (e.clientX - rect.left + 10) + 'px';
      tooltip.style.top = (e.clientY - rect.top - 40) + 'px';
      tooltip.classList.add('visible');

      // 不立即更新侧边栏，仅在点击时更新，或保持 hover 高亮
      // 此处选择点击更新侧边栏，hover 仅显示 tooltip
    } else {
      canvas.style.cursor = 'default';
      tooltip.classList.remove('visible');
    }
  }

  function handleClick(e) {
    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;

    const padding = { left: 50, right: 30 };
    const chartWidth = canvas.width - padding.left - padding.right;
    const gap = chartWidth / 5;
    const barWidth = chartWidth / 5 / 2;

    for (let i = 0; i < 5; i++) {
      const xStart = padding.left + i * gap + (gap - barWidth) / 2;
      const xEnd = xStart + barWidth;
      if (mouseX >= xStart && mouseX <= xEnd) {
        activeIndex = i;
        drawChart();
        updateDetail(i);
        break;
      }
    }
  }

  // 6. 事件监听
  metricSelect.addEventListener('change', (e) => {
    currentMetric = e.target.value;
    activeIndex = -1;
    drawChart();
    updateDetail(-1);
  });

  resetBtn.addEventListener('click', () => {
    currentMetric = 'rph';
    metricSelect.value = 'rph';
    activeIndex = -1;
    drawChart();
    updateDetail(-1);
  });

  canvas.addEventListener('mousemove', handleMouse);
  canvas.addEventListener('mouseleave', () => tooltip.classList.remove('visible'));
  canvas.addEventListener('click', handleClick);

  // 键盘支持
  canvas.setAttribute('tabindex', '0');
  canvas.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') {
      activeIndex = Math.min(activeIndex + 1, 4);
      drawChart();
      updateDetail(activeIndex);
    } else if (e.key === 'ArrowLeft') {
      activeIndex = Math.max(activeIndex - 1, 0);
      drawChart();
      updateDetail(activeIndex);
    } else if (e.key === 'Enter' || e.key === ' ') {
       // 触发点击效果
       drawChart();
       updateDetail(activeIndex);
    }
  });

  // 初始化
  drawChart();

})();
